export const toast=(message)=>{const e=$('#toast');e.textContent=message;e.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('visible'),4200)};
export async function api(path,options={}){
  const headers={...(options.headers||{})};
  if(options.body&&typeof options.body!=='string'&&!(options.body instanceof Blob)&&!(options.body instanceof ArrayBuffer)){options.body=JSON.stringify(options.body);headers['Content-Type']='application/json'}
  if(state.csrf)headers['X-CSRF-Token']=state.csrf;
  const response=await fetch(path,{...options,headers,credentials:'same-origin'});
  let data;try{data=await response.json()}catch{throw Error('El servidor no respondió correctamente')}
  if(!response.ok)throw Error(data.error||'No se pudo completar la solicitud');return data;
}
